// One-off seed: migrates the 13 static rules previously hand-maintained in
// public/_redirects into "redirect" documents in Sanity, so an editor can
// manage them from Studio going forward. That file is now generated by
// scripts/generate-redirects.mjs — don't hand-edit it after this runs.
// Uses createOrReplace with deterministic _ids derived from the source path,
// so it's safe to re-run.
//
// Usage: node --env-file=.env scripts/seed-redirects.mjs

const { PUBLIC_SANITY_PROJECT_ID, PUBLIC_SANITY_DATASET, SANITY_API_TOKEN } = process.env;

for (const [name, value] of Object.entries({ PUBLIC_SANITY_PROJECT_ID, PUBLIC_SANITY_DATASET, SANITY_API_TOKEN })) {
  if (!value) {
    console.error(`Missing required env var: ${name} (load .env first, e.g. run with --env-file=.env)`);
    process.exit(1);
  }
}

const dataset = PUBLIC_SANITY_DATASET || 'production';

const REDIRECTS = [
  { source: '/course-en', destination: '/about-us' },
  { source: '/course-is', destination: '/about-us' },
  { source: '/direct-booking', destination: '/about-us' },
  { source: '/godo', destination: '/booking-engine' },
  { source: '/godo-updated', destination: '/booking-engine' },
  { source: '/hotelmanagers', destination: '/' },
  { source: '/showroom', destination: '/custom-website' },
  { source: '/skilmalar-is', destination: '/' },
  { source: '/new/custom-website', destination: '/custom-website' },
  { source: '/new/blog/master-direct-bookins-with-hitels', destination: '/blog/master-direct-bookins-with-hitels' },
  { source: '/new/blog/how-a-great-hotel-website-builds-trust-before-check-in', destination: '/blog/how-a-great-hotel-website-builds-trust-before-check-in' },
  { source: '/new/blog/how-to-respond-to-negative-hotel-reviews', destination: '/blog/how-to-respond-to-negative-hotel-reviews' },
  { source: '/new/pricing', destination: '/pricing' },
  { source: '/new/home', destination: '/' },
];

const slugify = (path) => path.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '');

const mutations = REDIRECTS.map(({ source, destination }) => ({
  createOrReplace: {
    _id: `redirect-${slugify(source)}`,
    _type: 'redirect',
    source,
    destination,
    permanent: true,
  },
}));

const res = await fetch(`https://${PUBLIC_SANITY_PROJECT_ID}.api.sanity.io/v2021-06-07/data/mutate/${dataset}`, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${SANITY_API_TOKEN}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({ mutations }),
});

const body = await res.json();
if (!res.ok) {
  console.error('Seed failed:', JSON.stringify(body, null, 2));
  process.exit(1);
}

console.log(`Seeded ${REDIRECTS.length} "redirect" documents.`);
console.log(JSON.stringify(body, null, 2));
